import{_ as t}from"./chunks/2bcbea751f7e49815a6f.CywLdGoY.js";import{_ as o}from"./chunks/8549cc296d59b11fd6cd.Qamv1ACt.js";import{_ as a,o as n,c as i,a5 as r}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"Why You Won’t Change (How To Reinvent Yourself)","description":"","frontmatter":{"title":"Why You Won’t Change (How To Reinvent Yourself)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/why-you-wont-change-how-to-reinvent-yourself.md","filePath":"en/letters/why-you-wont-change-how-to-reinvent-yourself.md"}'),s={name:"en/letters/why-you-wont-change-how-to-reinvent-yourself.md"};function h(l,e,p,u,d,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="why-you-won-t-change-how-to-reinvent-yourself" tabindex="-1">Why You Won’t Change (How To Reinvent Yourself) <a class="header-anchor" href="#why-you-won-t-change-how-to-reinvent-yourself" aria-label="Permalink to &quot;Why You Won’t Change (How To Reinvent Yourself)&quot;">​</a></h1><p>Dan Koe · 2022-06-18 · <a href="https://thedankoe.com/letters/why-you-wont-change-how-to-reinvent-yourself/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/why-you-wont-change-how-to-reinvent-yourself">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/QBESNoCeZWY?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I was a boy scout when I was a kid.</p><p>I would show up to my former church on Tuesday nights, put a 3 finger salute in the air, and recite the scout oath.</p><p>Our troop would discuss our weekly agenda, work towards merit badges that interested us, and plan our next camping trip.</p><p>Every year we had what was called a “High Adventure” trip.</p><p>These adventures were week-long camping trips. Sometimes we would go and build our own snow caves to sleep in. Others we would join other scout troops from across the state, work towards different merit badges (like the survival merit badge where I had to create a shelter out of tree bark and “survive” the night), and during the night we would sit around the campfire and play games.</p><p>One year we decided to go to Catalina Island. We had the lofty goal of kayaking around the island and camping on different beaches along the way.</p><p>When that day came, we drove to California, got on the fairy, and landed in Catalina after an hour of card games and virgin Piña Coladas.</p><p>Since we got there late we had to <em>rush to our kayak rentals and “set sail”</em> almost immediately. No downtime, a tad stressful.</p><p>We partnered up, strapped our oversized duffle bags to the back of the small boats, and banked on our previous canoeing (a canoe is a boat similar to a kayak) merit badge to have made us skilled enough to navigate the next 5 hours in the ocean.</p><h2 id="life-comes-in-waves" tabindex="-1">Life Comes In Waves <a class="header-anchor" href="#life-comes-in-waves" aria-label="Permalink to &quot;Life Comes In Waves&quot;">​</a></h2><p>The waters were smooth for about an hour. No problems. Peaceful.</p><p>That was until the ocean’s waves started getting a bit deeper. We thought it was temporary because we couldn’t see the storm that was coming over the other side of the island. We were too close to the cliffside to see anything aside from the clear skies to our right.</p><p>Long story short, <em>we got caught in the middle of the storm</em> halfway through our adventure.</p><p>The waves grew to a minimum of 10 feet in size.</p><p>Our group started to get split up — the strong and able in the front, the weak in the back.</p><p><strong>My buddy and I flipped our kayak multiple times.</strong> Soaked. Cold. Nearly losing our paddles. Can’t hear a thing. Dense and heavy rain needling the parts of our body that were above water.</p><p>My duffel bag fell off at one point — soaking all of my food and clothes – making me dive in to grab it and attempt at tying it back on.</p><p>Not to mention… we were paddling <em>against</em> the strong winds. Making barely any progress towards our beach destination.</p><p><strong>This was the one moment in my life where I truly thought my life was over.</strong></p><p>The scout leaders’ orange paddles could only be seen when they were at the bottom of a wave when we were at the top. We lost them after about the first 30 minutes of the storm.</p><p>My kayak buddy and I went through phases of paddling as hard as we can and accepting our demise. Slouched in the storm. Defeated. Giving in to the waves and praying that they didn’t slam us into the cliffside that was ~100-200 feet away from us.</p><p>Time was a blur at this point. We eventually saw the shore, regained hope, and paddled as hard as we possibly fucking could to reach land.</p><p>Crashing on shore, we dragged our kayak onto the beach and collapsed. All of us slightly convulsing from the cold trying to expose as much of our bodies to the sun as we could.</p><p>Those that fell behind showed up with the island rescue team about an hour later. All of my food and clothes were still soaked (and ended up getting eaten by birds while we were sleeping).</p><p>Safe to say, we had to call the trip short and left the next day.</p><p>There is a lot we can learn from this story, it mimics <a href="https://thedankoe.com/if-you-feel-lost-understand-these-3-phases-of-life/" target="_blank" rel="noreferrer">life’s cycles of intensity</a> quite well — but I want to paint a different picture.</p><h2 id="high-highs-and-low-lows" tabindex="-1">High Highs And Low Lows <a class="header-anchor" href="#high-highs-and-low-lows" aria-label="Permalink to &quot;High Highs And Low Lows&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>When we were on top of the waves, there was hope.</p><p>When we were deep in the trenches, hope was scarce.</p><p>When you feel on top of the world, nothing can stop you.</p><p>When you fall to the bottom of the ocean, anything can stop you.</p><blockquote><p>You’re out in the cold, you start shivering, why? Because you’re resisting the cold, you are tightening your muscles against the cold and you get the staggers. Take it easy, go with the cold, relax.\\</p><p>— Alan Watts</p></blockquote><p>In classical mechanics, <em>a harmonic oscillator is a system that tries to maintain equilibrium</em> (homeostasis).</p><p>The 80/20 of what you need to know is that when equilibrium is displaced, it bounces back in the same amount the opposite direction and eventually brings itself back to equilibrium.</p><p>Our mind is no different.</p><p>The high highs that we grow to look forward to in life are <em>always</em> followed by a low low. Always. If you don’t recognize it as a low low – congratulations, you have developed a certain level of mindfulness when interacting the battles that come while you are deep in the trenches.</p><p>Our mind is a network of complex systems that have been conditioned over time through positive and negative feedback. That’s how systems work, right?</p><p>If you receive negative feedback, you won’t do that again.</p><p>If you receive positive feedback, you will do that again.</p><p>If you consistently receive positive feedback for doing one specific thing, it becomes engrained in your psyche. The action, belief, or thought pattern become habitual. They happen on autopilot.</p><p>Like training a dog. They don’t understand words, but they can associate tones and patterns with certain meanings — positive and negative. If a dog has sub-optimal behavior, you use a certain tone or strategy to give the dog negative feedback. Do this enough times and they will eventually change their behavior, which you can reinforce (condition) with positive feedback.</p><p>This malleable nature of our mind can be very dangerous (when unconscious) or very beneficial (when conscious).</p><p>This shows that we have the power to recondition, reprogram, or rewire our brain — but our harmonic oscillator of a mind won’t let us off that easy.</p><p><em><strong>Shameless Mid Koe Letter Plug</strong>: <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can join Modern Mastery for $5</a> — join 1000+ members and access 170+ life and business strategies, roadmaps, live trainings, &amp; personalized help.</em></p><h2 id="layers-of-identity" tabindex="-1">Layers Of Identity <a class="header-anchor" href="#layers-of-identity" aria-label="Permalink to &quot;Layers Of Identity&quot;">​</a></h2><p>If you want to change your life, you must change your identity.</p><p>A healthy person does not see eating healthy as a chore. <em>They ARE a person that eats healthy</em>. There is no other option. It is enjoyable to them.</p><p>A businessman does not see focused work as a burden every morning. <em>They ARE a person who gets work done every morning.</em></p><p>Changing your beliefs, identity, and life is not as simple as it sounds.</p><p>I want you to think of your mind as a city. Seattle Washington in specific.</p><p>In 1889, a glue pot tipped over resulting in a fire that destroyed a large portion of the city. Why?</p><p>Aside from the person that thought it would be wise to throw water on the flaming glue (making it spread fast) the city was built on a terrible foundation. Wooden buildings. Wooden sewage system. Poor construction — the lot of it.</p><p>The human psyche is wired for survival. When your beliefs, identity, or life is threatened — the brain signals the body, your focus starts to narrow, and you give a bit too much attention to the thoughts flooding your mind. Equilibrium is displaced and your mind starts reacting accordingly to bring you back to homeostasis.</p><p>The problem is that we live in a completely different world than our ancestors. We are rarely threatened on a physical level. Most of us have shelter, access to food, and the ability to make a living.</p><p>Humans are the only beings that equate the death of a belief to physical death.</p><p>This survival mechanism can be dangerous and damaging. If you attempt to change your identity by making one small change, you displace equilibrium (or tip over a pot of glue) and potentially set fire to a portion of the city that has been built in your mind over years of construction (conditioning).</p><p>When you try reconstruct a piece of your city, it may threaten the entire foundation. When you are at the bottom of the wave, you can’t see anything. You may lose hope for reaching the shore. You may tip over your kayak a few times.</p><p>When you are deep in the trenches of life, you may not interpret it as a good thing. You may take it as negative feedback — conditioning a faulty systematic thought pattern — and avoid anything that threatens the identity that isn’t conducive to a high quality of life.</p><p>That’s the challenge with all of this. New Rome is built on top of Ancient Rome (and no, it wasn’t built in a day!). New Seattle is built on top of Old Seattle.</p><p>All of the buildings, foundations, streets, and other networks are all interconnected. Layers upon layers that rely on each other for proper function. An array of systems that work in unison to perform what it was meant to perform. Removing a specific part may cause temporary damage to how the systems function.</p><p>Similar to your identity — we make sense of ourselves through the layers of stories, beliefs, and engrained thought patterns that construct how optimally our mind operates.</p><p>Would I cease to exist if I reconstructed my story? If I revealed and recreated the traumas of my past? What if I questioned my hardset religious beliefs? Would I still be “me” if my entire life didn’t revolve around the church? What would my life look like if I didn’t do the same thing day after day?</p><p>It would be difficult to make sense of — that’s for sure.</p><h2 id="how-to-reinvent-yourself" tabindex="-1">How To Reinvent Yourself <a class="header-anchor" href="#how-to-reinvent-yourself" aria-label="Permalink to &quot;How To Reinvent Yourself&quot;">​</a></h2><p>There are 2 routes to reinventing yourself:</p><p><strong>1) Hit rock bottom.</strong></p><p>By feeling into the lowest of lows in your life, <a href="https://thedankoe.com/get-mad-at-where-you-are-in-life/" target="_blank" rel="noreferrer">you start to become fed up with your life situation.</a></p><p>You become hyper aware of what is holding you back. You dig deep into the layers of your identity and find just the right piece to remove in order to launch in the opposite direction.</p><p>This comes with a lot of pain and suffering — and is often uncontrollable. Burning down your metaphorical city may cause some deeper issues leading to another rock bottom years later in life.</p><p>Everybody I have met that hit rock bottom was from an unfortunate hand they were dealt with by life itself.</p><p>There is a better option. One that is completely within your control.</p><p><strong>2) Stack small wins.</strong></p><p>Everybody has heard of James Clear’s “One Percent Better Everyday” mantra.</p><p>It holds a lot of power.</p><p>When you reconstruct your city piece by piece, you build what would be New Seattle (without having to burn down half the city).</p><p>Where do you begin?</p><p>By getting crystal clear on your vision and anti-vision.</p><blockquote><p>If you don’t know what you want, understand what you don’t want and work in the opposite direction.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1537030087874420738?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 15, 2022</a></p></blockquote><p>Thanks to our brains negativity bias, it is easy to observe what you don’t want and start working in the opposite direction.</p><p>When you <a href="https://thedankoe.com/how-to-create-a-life-of-meaning-money-impact-as-fast-as-humanly-possible/" target="_blank" rel="noreferrer">outline a vision for your future</a>, it will shine the light of awareness on your blindspots.</p><blockquote><p>If you are lost, the answer is education.\\</p><p>If you are educated, the answer is action.\\</p><p>If you are acting, the answer is consistency.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1508796620569206784?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">March 29, 2022</a></p></blockquote><p>As you reverse engineer your vision into 10-year, 1-year, and monthly goals — you start to gain clarity on what you need to do in order to actualize that vision.</p><p>Now, we can break things down into priority tasks.</p><p>From there — and by far the most important step — is reducing the friction of taking action.</p><p>What is the smallest mental, physical, emotional, or financial step you can take?</p><p>Is it putting on your gym shoes and walking out the door?</p><p>Is it moving one leg and getting off of the couch?</p><p>Is it investing $25 into a course to show you are serious about improving your skill set?</p><p>Is it reading the first word of a book or writing the first word of your own book?</p><h2 id="actively-construct-your-life" tabindex="-1">Actively Construct Your Life <a class="header-anchor" href="#actively-construct-your-life" aria-label="Permalink to &quot;Actively Construct Your Life&quot;">​</a></h2><p>This is not an easy process. You are still in a metaphorical kayak in the middle of a storm. Life is chaotic. Ordering consciousness through vision and goal setting is how we gain a sense of certainty and control over our life.</p><p>Since we are in an age similar to 5th century BC — there is information and an abundance of ideas circulating our world. People are losing trust in externally assigned hierarchies of goals whether it be from corporate culture, organized religions, or formal education.</p><p>Because of this, you must play an active role in constructing your life. This requires personal responsibility, massive self-belief, and the realization that nobody is coming to save you.</p><p>It is in your hands to <a href="https://thedankoe.com/how-to-make-money-as-a-creative-on-the-internet/" target="_blank" rel="noreferrer">collect and organize the abundant information</a> in the world and organize it in a way that will result in a fulfilling income source, radiating health, an ordered mind, and a connected spirit.</p><blockquote><p>Hard pill to swallow:\\</p><p>Most of your limitations are self imposed. If you want something, there’s always a way – your mind just won’t let you see it.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1381538141895528448?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">April 12, 2021</a></p></blockquote><p>If you believe you are in the middle of a storm, you will be.</p><p>If you believe you are having fun on a roller coaster of waves, you will have fun.</p><p>How do you actively construct your life?</p><p>Through consciousness, creativity, and intention.</p><p>The easiest way to do this is by treating every facet of your life as a project.</p><p><img src="'+o+'" alt=""></p><p>Here is all you need to start changing your life:</p><ol><li>Purchase a blank notebook</li><li>In big letters write “My Scientific Journal”</li><li>Treat your mind, body, spirit, and business as a lifelong project</li><li>Note observations, test small changes, analyze the results, and double down on what works</li></ol><p>Stay conscious and aware through silent observation (that can apply to your mental, physical, financial, and spiritual projects).</p><p>Self-educate to expand awareness and uncover new paths.</p><p>Hypothesize and experiment with solutions that will solve your problems.</p><p>Analyze the result and get feedback that will begin to rewire the network of systems in your mind.</p><p>Document a replicable process that can help other people and bring you <em>more</em> feedback.</p><p>Rinse and repeat.</p><p>It took 18+ years to condition you to the point you are now.</p><p>Don’t expect much progress overnight.</p><p>That, my friends, is how you reinvent yourself.</p><p>— Dan Koe</p><p><strong>What Happened This Week</strong></p><p>A new YouTube video went out about my story. How I failed at most online business models and turned it into a half-mil a year one-person business.</p><p><a href="https://www.youtube.com/watch?v=L9qh1-T_YVo" target="_blank" rel="noreferrer">You can watch it here.</a></p><p>We are prepping for the live training next week with Dakota Robertson inside Modern Mastery. We will be going over how to get into Twitter Ghostwriting, landing your first client, and the skills you need to learn.</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Koe Letter readers can join for $5 here.</a></p><p>For those that are wondering why there haven’t been podcast episodes recently — I’ve had to prioritize my attention due to the launch of Digital Economics. The podcast has always been the first thing to go when I need to refocus. I will either get back on the same schedule soon or start doing bite size big ideas of the week (5-10 minute episodes).</p><p>If you have suggestions on a podcast style you’d like to see, let me know by replying to this email!</p>',124)])])}const m=a(s,[["render",h]]);export{w as __pageData,m as default};
